ype="doc",args={"YEL娜娜米：放心吧，我就在这里暗中观察，有什么异常你直接来这找我便是，也可用那响箭唤我。NOR"}}},caozuoName3="告知",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL娜娜米：哦？这么嚣张？我这就去给他擒住！NOR"}},{type="gaintab",args={"32005",2}},{type="outobject",args={"hdrole03002a"}},{type="gaintab",args={"32001",1}}},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"32003",1}}}},autoResult1={{type="outobject",args={"hdrole03002a"}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"32004",1}}}},autoResult2={{type="outobject",args={"hdrole03002a"}}},autoCondition3={relation="and",conditions={{type="equaltab",args={"32005",1}}}},autoResult3={{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdrole03003={id="hdrole03003",baseId="hdnpc0303",combatid={1,1001},name="神秘人",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL神秘人：武学多练不过来？那你更来对了！我大哥可以为你解忧啊！我大哥有一丹药，可以让武学突飞猛进、一日千里啊！明儿他也会来此！NOR"}},{type="timer",args={0.7,"timer30203",{{"doc",{"YEL神秘人：嘿嘿嘿，上到武林绝学，下到江湖秘籍，我这都有！价格绝对公道！若是……少侠加入我们瞒天教，我们还免费赠送少侠三本秘籍，随便挑！NOR"}}}}}},caozuoName2="呔！何方妖孽",buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"CYN你大喝一声，将神秘人吓得一愣，你趁机便将他擒住，随后将响箭放出。NOR"}},{type="timer",args={0.7,"timer30204",{{"doc",{"CYN未待片刻之后，娜娜米便赶了过来，将神秘人五花大绑后装进了麻袋中。NOR"}}}}},{type="timer",args={1.4,"timer30205",{{"doc",{"YEL神秘人：为什么要抓我！我只是看得多，记得牢罢了！NOR"}}}}},{type="itemout",args={"tzhddj0